\label{fa2:p1:c02:quotient-map}
The formula is a well-defined seminorm, and is a norm exactly when $M$
is closed. In that case $q$ is linear, surjective, contractive, and open;
more precisely $q(B_E(x,r))=B_{E/M}(q(x),r)$. A linear map $T:E\to F$
vanishing on $M$ factors uniquely as $\widetilde Tq$, and if $T$ is
bounded then $\widetilde T$ is bounded with $\norm{\widetilde T}=\norm{T}$.

\label{fa2:p1:c02:quotient-complete}
If $E$ is Banach and $M$ is closed, then $E/M$ with the quotient norm is
Banach.

\label{fa2:p1:c03:operator-complete}
If $F$ is Banach and $E$ is any normed space, then $\Lin{E}{F}$ is
Banach in the operator norm.

\label{fa2:p1:c04:evaluation-contractive}
For each $x$, $J_E(x)$ is a continuous linear functional on $E'$.
The map $J_E$ is linear and $\norm{J_E x}\leq\norm{x}$.

\label{fa2:p1:c07:weak-boundedness}
For any normed space $E$, a set $A\subset E$ is norm bounded exactly
when $\{f(x):x\in A\}$ is bounded for every $f\in E'$.

\label{fa2:p1:c13:scalar-product-compactness}
If $(D_i)_{i\in I}$ are closed bounded scalar disks centered at
zero, their product is compact in its product topology.

\label{fa2:p1:c13:subsequences}
If $E$ is separable and $(f_n)$ is norm bounded in $E'$, some
subsequence converges in $\sigma(E',E)$ to an element of $E'$.

\label{fa2:p1:c14:goldstine}\label{fa2:p1:goldstine}
For every normed space $E$, $J_E(B_E)$ is dense in $B_{E''}$ for
$\sigma(E'',E')$ relative to that ball.

\label{fa2:p1:c14:radon-riesz}
In a uniformly convex normed space, if $x_n\to x$ weakly and
$\limsup_n\norm{x_n}\leq\norm x$, then $x_n\to x$ in norm.

\label{fa2:p1:eberlein-smulian}
For a subset $A$ of a normed space $E$, the following are equivalent:
\begin{enumerate}
\item its weak closure is weakly compact;
\item every sequence in $A$ has a subsequence weakly convergent in $E$;
\item every sequence in $A$ has a weak cluster point in $E$.
\end{enumerate}
In particular, a weakly closed set is weakly compact if and only if it is
weakly sequentially compact.  On a weakly closed set these conditions are
also equivalent to countable compactness for the weak topology.
Thus defining relative countable compactness by countable compactness
of the weak closure gives the same relative notion as condition 1.

\label{fa2:p1:separable-tvs-dual-compact}
If $E$ is a separable TVS, every weakly star compact subset $K$ of
its continuous dual is metrizable.

\label{fa2:p1:james}
Let $A$ be a nonempty weakly closed subset of a real or complex Banach
space $E$.  The following are equivalent:
\begin{enumerate}
\item $A$ is weakly compact;
\item for every $f\in E'$, the finite supremum
      $\sup_{x\in A}|f(x)|$ is attained at a point of $A$;
\item for every continuous real linear functional $u$ on the underlying
      real space, $\sup_A|u|$ is finite and attained;
\item for every such $u$, $\sup_Au$ is finite and attained.
\end{enumerate}
Consequently $E$ is reflexive if and only if every member of $E'$
attains its norm on $B_E$.

\label{fa2:p1:orlicz-pettis}
If every subseries of $\sum x_n$ converges weakly in a Banach space,
then the series converges unconditionally in norm.

\label{fa2:p1:dual-bases}
For a basis $(x_n)$ of $E$ let $F=\overline{\operatorname{span}}\{x_n'\}$
in $E'$. The coordinate functionals form a basic sequence. The basis
is shrinking precisely when $F=E'$, equivalently
$\|f|_{\overline{\operatorname{span}}\{x_j:j>n\}}\|\to0$ for every
$f\in E'$. It is boundedly complete if every scalar sequence with
bounded initial sums $\sum_{j\leq n}a_jx_j$ has a convergent series.
The following hold:
\begin{enumerate}
\item $(x_n')$ is boundedly complete in $F$ if and only if $(x_n)$ is
shrinking;
\item $(x_n')$ is shrinking in $F$ if and only if $(x_n)$ is boundedly
complete;
\item $E$ is reflexive if and only if its basis is both shrinking and
boundedly complete.
\end{enumerate}

\label{fa2:p1:strong-rotundity}
The following are equivalent for a normed space:
\begin{enumerate}
\item for each $f\in E'$ with $\|f\|=1$, the diameters of the slices
$\{x:\|x\|\leq1,\operatorname{Re}f(x)>1-\delta\}$ tend to zero;
\item every sequence of unit vectors with
$\operatorname{Re}f(x_n)\to1$ for one norm-one $f$ is Cauchy;
\item every minimizing sequence in a nonempty convex set, for
distance to any fixed point, is Cauchy.
\end{enumerate}
This property, strong rotundity, implies strict convexity and
Radon--Riesz. In a Banach space it makes all such minimizing sequences
convergent. Reflexive strictly convex spaces with Radon--Riesz have
this property; in particular reflexive locally uniformly convex
spaces do.

\label{fa2:p1:c24:schauder}
A continuous self-map $T:C\to C$ of a nonempty compact convex subset
of a real or complex normed space has a fixed point.

\label{fa2:p1:c24:compact-hull}
If $Q$ is a compact subset of a Banach space, then
$\cl\operatorname{conv}Q$ is compact in norm.

\label{fa2:p1:schauder}
A continuous self-map of a nonempty compact convex subset of a
Hausdorff LCS has a fixed point.

\label{fa2:p1:markov-kakutani}
A commuting family of continuous affine self-maps of a nonempty
compact convex subset of an LCS has a common fixed point.

\label{fa2:p1:closed-sums}
Let $G,L$ be closed subspaces of a Banach space $E$.  The following
conditions are equivalent:
\begin{enumerate}
\item $G+L$ is closed;
\item there is $C$ such that every $x\in G+L$ has a decomposition
      $x=g+l$ with $\|g\|+\|l\|\le C\|x\|$;
\item there is $C$ such that
      $\operatorname{dist}(g,G\cap L)\le C\operatorname{dist}(g,L)$
      for $g\in G$;
\item there is $C$ such that, for every $x\in E$,
\[
 \operatorname{dist}(x,G\cap L)
 \le C\bigl(\operatorname{dist}(x,G)+\operatorname{dist}(x,L)\bigr).
\]
\end{enumerate}
Moreover $G+L$ is closed if and only if $G^\perp+L^\perp$ is norm
closed in $E'$.  In that case
$(G\cap L)^\perp=G^\perp+L^\perp$.

\label{fa2:p1:weak-sequential-completeness}
Reflexive Banach spaces are weakly sequentially complete.  The dual
of a Banach space is weakly star sequentially complete.

\label{fa2:p1:weierstrass}
Every continuous scalar function on a compact real interval is a
uniform limit of polynomials.

\label{fa2:p1:asplund-complex}
The simultaneous renorming theorem also holds for two equivalent
complex norms with the stated primal and complex-dual strictness.

\label{fa2:p2:parallelogram}
A real or complex normed space is induced by an inner product iff
$\|x+y\|^2+\|x-y\|^2=2\|x\|^2+2\|y\|^2$.

\label{fa2:p2:gantmacher}
For $T\in\faB(X,Y)$ the following are equivalent:
$T$ is weakly compact; $T''X''\subset J_Y Y$;
$T':(Y',\sigma(Y',Y))\to(X',\sigma(X',X''))$ is continuous.
Also $T$ is weakly compact iff $T'$ is weakly compact. Weakly compact
operators form a norm-closed two-sided ideal.

\label{fa2:p2:linfinity-weak-l1}
If $g_n\rightharpoonup0$ in the Banach space $L^\infty(\mu)$, then
$\int_A|g_n|\,d\mu\to0$ for every measurable $A$ of finite measure.

\label{fa2:p2:banach-analytic}
A function $f:U\to X$, $U\subset\mathbb C$ open and $X$ Banach, is
norm analytic iff $x'f$ is scalar analytic for every $x'\in X'$.

\label{fa2:p2:index-components}
On a fixed complex Hilbert space two Fredholm operators belong to the
same norm-path component iff their indices agree.

\label{fa2:p2:one-sided-fredholm}
For a bounded map $T:E\to F$ between Banach spaces, the following
three right-sided conditions are equivalent:
\begin{enumerate}
\item the range is closed of finite codimension and $\ker T$
      is complemented in $E$;
\item $TS=I_F+K$ for some bounded $S:F\to E$ and compact $K$ on $F$;
\item $TU=I_F-P$ for some bounded $U:F\to E$ and finite-rank
      projection $P$ on $F$.
\end{enumerate}
In the last form one may choose $\operatorname{rank}P=
\operatorname{codim}\operatorname{Ran}T$.
The following three left-sided conditions are likewise equivalent:
the range is closed and complemented and the kernel finite dimensional;
$ST=I_E+K$ with $K$ compact; and $UT=I_E-Q$ with $Q$ a
finite-rank projection. One may choose
$\operatorname{rank}Q=\dim\ker T$.
These are the general Banach-space statements of
\cite[Problem 38, A--B]{B01}; a one-sided inverse modulo compacts
does not remove the stated complement condition.

\label{fa2:ap:counterexample}
There exists a separable real reflexive Banach space without AP, and consequently
without a Schauder basis. There also exists a complex Banach space without AP.

\label{fa2:p4:sobolev-one}
If $d>1$ and $u\in C_c^1(\mathbb R^d)$, then
$\pfnorm u_{d/(d-1)}\le C_d\sum_j\pfnorm{\partial_ju}_1$.

\label{fa2:p4:besicovitch}
There is a compact planar set of Lebesgue measure zero containing
a line segment of length one in every unoriented direction.

\label{fa2:p4:hardy-grand-atomic}
If $f\in L^1$ and $G=\mathcal G_N f\in L^1$, then
$f\in H^1_{\rm at}$ and $\|f\|_{H^1_{\rm at}}\le C\|G\|_1$.
